func parseHexByte(hex string, out *uint8) (bool, error) {
	var val uint8
	for i := 0; i < len(hex); i++ {
		c := hex[i]
		var digit uint8
		switch {
		case '0' <= c && c <= '9':
			digit = c - '0'
		case 'a' <= c && c <= 'f':
